#![allow(
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::panic,
    missing_docs,
    reason = "standard pack conformance"
)]

//! The UBL 2.3 Invoice pack is an ordinary admitted pack: its source schema
//! (generated by the generic XSD reader from hash-pinned originals), its
//! mapping onto the REA canon and its declared gaps check like any system
//! pack, with no UBL-specific Rust anywhere.
use norn_checker::{
    ArtifactRef, EntityArtifactSetContext, check_artifact_set,
    lint::coverage::{MemberRef, MemberStatus},
    mapping::{CompiledMapping, SourceDocument, compile_mapping_artifact},
};
use norn_ir::{ArtifactEnvelope, provenance::UtcTimestamp};
use serde_json::json;
use std::{collections::BTreeSet, fs, path::PathBuf};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}
fn artifacts() -> Vec<ArtifactEnvelope> {
    ["core", "packs/canon", "packs/ubl"]
        .into_iter()
        .flat_map(|dir| {
            fs::read_dir(root().join(format!("registry/{dir}/artifacts"))).expect("directory")
        })
        .map(|entry| {
            serde_json::from_str(
                &fs::read_to_string(entry.expect("entry").path()).expect("artifact"),
            )
            .expect("envelope")
        })
        .filter(|a: &ArtifactEnvelope| {
            ![
                "commerce.SalesOrder.entity",
                "core.Order.interface",
                "core.Entitlement.entity",
                "identity.BusinessUnit.entity",
                "location.Region.entity",
                "location.Space.entity",
                "party.Brand.entity",
            ]
            .contains(&a.artifact_id.as_str())
        })
        .collect()
}
fn compiled() -> CompiledMapping {
    let set = artifacts();
    let mapping = set
        .iter()
        .find(|a| a.artifact_id == "ubl.invoice.mapping")
        .expect("mapping");
    let source = set
        .iter()
        .find(|a| a.artifact_id == "ubl.invoice.source")
        .expect("source");
    let wire = serde_json::to_value(mapping).expect("wire");
    assert_eq!(
        wire["payload"]["source"]["sha256"],
        ArtifactRef::of(source).expect("source pin").sha256,
        "records.ts must pin the generated source schema"
    );
    compile_mapping_artifact(mapping, &set, &[]).unwrap_or_else(|d| panic!("ubl: {d:#?}"))
}

#[test]
fn ubl_pack_is_admitted_with_the_canon() {
    let (base, candidate): (Vec<_>, Vec<_>) = artifacts()
        .into_iter()
        .partition(|a| a.artifact_id.starts_with("core.") || a.artifact_id.starts_with("std."));
    let diagnostics = check_artifact_set(
        &candidate,
        &EntityArtifactSetContext {
            registry: &BTreeSet::new(),
            base: &base,
            tenant: None,
        },
    );
    assert!(
        diagnostics
            .iter()
            .all(|d| d.severity != norn_ir::DiagnosticSeverity::Error),
        "{diagnostics:#?}"
    );
}

#[test]
fn ubl_invoice_maps_to_a_claim_between_two_parties() {
    let mapping = compiled();
    let record = json!({
        "ID": "INV-1", "IssueDate": "2026-11-01", "DueDate": "2026-12-01",
        "DocumentCurrencyCode": "EGP", "payable_amount": "100.00",
        "AccountingSupplierParty": {"Party": {"EndpointID": "S-1"}},
        "LegalMonetaryTotal": {"PayableAmount": "100.00"}, "InvoiceLine": [{"ID": "1"}],
        "supplier_endpoint": "S-1", "supplier_name": "Synthetic Supplier",
        "customer_endpoint": "C-1", "customer_name": "Synthetic Customer",
    });
    let documents =
        [SourceDocument::from_json("InvoiceType", &record.to_string(), None).expect("evidence")];
    let mapped = mapping
        .apply(&documents, &UtcTimestamp("2026-11-11T00:00:00Z".into()))
        .unwrap_or_else(|d| panic!("mapping: {d:#?}"));
    let types: BTreeSet<_> = mapped.iter().map(|r| r.object_type.as_str()).collect();
    assert_eq!(types, BTreeSet::from(["canon.Invoice", "canon.Party"]));
    assert_eq!(
        mapped
            .iter()
            .filter(|r| r.object_type.as_str() == "canon.Party")
            .count(),
        2
    );
}

#[test]
fn ubl_payable_amount_is_a_declared_gap_not_a_guessed_money_amount() {
    let mapping = compiled();
    let coverage = mapping
        .coverage()
        .iter()
        .find(|c| c.target.as_str() == "canon.Invoice")
        .expect("coverage");
    let amount = coverage
        .member(&MemberRef::Property(norn_ir::PropertyId(
            "amount".to_owned(),
        )))
        .expect("explicit gap");
    assert!(matches!(amount.status, MemberStatus::Gap { .. }));
}
